1	package edgefleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"time"
9		"unicode/utf8"
10	)
11	
12	// Heartbeat is one telemetry record reported by a node.
13	//
14	// JSON input uses snake_case field names:
15	//
16	//	node          string   node id (required, non-empty)
17	//	seq           integer  sequence number (required, > 0)
18	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00
19	//	                      (required; year 0000-9999, numeric offset hour 00-23
20	//	                      and minute 00-59 on the minute — +24:00 and a folded
21	//	                      offset such as +00:60 are rejected, not normalised)
22	//	version       string   version (required, non-empty, valid Unicode text)
23	//	height        integer  block height (required, >= 0)
24	//	missed        integer  cumulative missed duties (required, >= 0)
25	type Heartbeat struct {
26		NodeID      string    `json:"node"`
27		Seq         int64     `json:"seq"`
28		CollectedAt time.Time `json:"collected_at"`
29		Version     string    `json:"version"`
30		Height      int64     `json:"height"`
31		Missed      int64     `json:"missed"`
32	}
33	
34	// heartbeatFields enumerates every field that must be explicitly provided.
35	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
36	
37	// fieldIssue classifies the way a field value violates a rule. Together with
38	// the field name and the offending numeric value it identifies the rule that
39	// failed, without carrying any wording. Each trust boundary renders the
40	// failure in its own message style and locates it in its own context, but the
41	// rules themselves — which values are legal — live in the check* functions
42	// below exactly once.
43	type fieldIssue int
44	
45	const (
46		issueEmpty            fieldIssue = iota // a required string is ""
47		issueInvalidUnicode                     // node id or version is not lossless text
48		issueNotPositive                        // integer must be > 0
49		issueNegative                           // integer must be >= 0
50		issueMissingInstant                     // collected_at is the zero instant
51		issueYearOutOfRange                     // collected_at year cannot be written by the saved format
52		issueOffsetOutOfRange                   // collected_at timezone offset is not a whole minute within ±23:59
53	)
54	
55	// fieldValueError names the field whose value rule was violated.
56	type fieldValueError struct {
57		field string
58		issue fieldIssue
59		value int64
60	}
61	
62	// checkNodeIDValue holds the single node-id value rule: non-empty, valid
63	// Unicode text. The raw-JSON boundary additionally checks the un-decoded
64	// token (see validateRawText); for a value already decoded from such a
65	// token the Unicode branch can never fire, but both submit entries and the
66	// stored-data read enforce the same rule through this one function.
67	func checkNodeIDValue(node string) *fieldValueError {
68		if node == "" {
69			return &fieldValueError{field: "node", issue: issueEmpty}
70		}
71		if !utf8.ValidString(node) {
72			return &fieldValueError{field: "node", issue: issueInvalidUnicode}
73		}
74		return nil
75	}
76	
77	// checkVersionValue holds the single version value rule: non-empty, valid
78	// Unicode text. The version is opaque text — Chinese, emoji and a literal "�"
79	// the user typed are all legal, and no format (digits and dots) is imposed —
80	// but it must be losslessly representable: a platform that silently rewrites
81	// invalid bytes to U+FFFD would merge distinct versions into one and make the
82	// version-skew judgement compare text the node never reported. The raw-JSON
83	// boundary additionally checks the un-decoded token (see validateRawText);
84	// for a value already decoded from such a token the Unicode branch can never
85	// fire, but both submit entries and the stored-data read enforce the same
86	// rule through this one function.
87	func checkVersionValue(version string) *fieldValueError {
88		if version == "" {
89			return &fieldValueError{field: "version", issue: issueEmpty}
90		}
91		if !utf8.ValidString(version) {
92			return &fieldValueError{field: "version", issue: issueInvalidUnicode}
93		}
94		return nil
95	}
96	
97	// checkPositiveInt holds the single positive-integer rule (seq).
98	func checkPositiveInt(field string, value int64) *fieldValueError {
99		if value <= 0 {
100			return &fieldValueError{field: field, issue: issueNotPositive, value: value}
101		}
102		return nil
103	}
104	
105	// checkNonNegativeInt holds the single non-negative-integer rule (height,
106	// missed). An explicit zero is genuine telemetry and passes.
107	func checkNonNegativeInt(field string, value int64) *fieldValueError {
108		if value < 0 {
109			return &fieldValueError{field: field, issue: issueNegative, value: value}
110		}
111		return nil
112	}
113	
114	// checkCollectedAtValue holds the context-free collected_at rules shared by
115	// every boundary:
116	//
117	//   - the instant must actually be present (not the zero time);
118	//   - its year must be 0000..9999, the four-digit range the saved RFC3339
119	//     form can write — a year outside it cannot be persisted at all;
120	//   - its UTC offset must be a whole number of minutes no larger than
121	//     ±23:59, the offsets the saved form can write exactly. A ±24:00 offset
122	//     is outside the 00..23 hour bound, and a sub-minute offset (e.g.
123	//     +08:00:30) would silently land on disk as a different instant.
124	//
125	// Checking the decoded instant covers a Heartbeat built directly in Go;
126	// values decoded from JSON text additionally pass validateCollectedAtText,
127	// because time.Parse folds an out-of-range textual offset (+00:60 -> +01:00)
128	// before an instant ever exists to inspect.
129	func checkCollectedAtValue(collected time.Time) *fieldValueError {
130		if collected.IsZero() {
131			return &fieldValueError{field: "collected_at", issue: issueMissingInstant}
132		}
133		if year := collected.Year(); year < minSavedYear || year > maxSavedYear {
134			return &fieldValueError{field: "collected_at", issue: issueYearOutOfRange, value: int64(year)}
135		}
136		if _, offset := collected.Zone(); !isWritableOffset(offset) {
137			return &fieldValueError{field: "collected_at", issue: issueOffsetOutOfRange, value: int64(offset)}
138		}
139		return nil
140	}
141	
142	// Year bounds of the four-digit RFC3339 year the saved format writes.
143	const (
144		minSavedYear = 0
145		maxSavedYear = 9999
146	)
147	
148	// maxWritableOffsetSeconds is 23:59, the largest magnitude UTC offset whose
149	// hour and minute fields both fit the RFC3339 numeric offset (hour 00..23,
150	// minute 00..59). 24:00 is out of range, not an alias for the next day.
151	const maxWritableOffsetSeconds = 23*3600 + 59*60
152	
153	// isWritableOffset reports whether a UTC offset in seconds can be written by
154	// the on-disk RFC3339 form without losing or folding anything: it must be a
155	// whole number of minutes (a sub-minute offset has no representation), and
156	// its magnitude must be no greater than ±23:59.
157	func isWritableOffset(offsetSeconds int) bool {
158		if offsetSeconds%60 != 0 {
159			return false
160		}
161		if offsetSeconds < 0 {
162			offsetSeconds = -offsetSeconds
163		}
164		return offsetSeconds <= maxWritableOffsetSeconds
165	}
166	
167	// formatOffsetSeconds renders a UTC offset in seconds the way it was
168	// declared: ±HH:MM for a whole-minute offset, ±HH:MM:SS when a sub-minute
169	// part is present, so an error can show the exact offset that could not be
170	// saved (e.g. +08:00:45 or -24:00).
171	func formatOffsetSeconds(seconds int) string {
172		sign := "+"
173		if seconds < 0 {
174			sign = "-"
175			seconds = -seconds
176		}
177		hour := seconds / 3600
178		minute := (seconds % 3600) / 60
179		if rem := seconds % 60; rem != 0 {
180			return fmt.Sprintf("%s%02d:%02d:%02d", sign, hour, minute, rem)
181		}
182		return fmt.Sprintf("%s%02d:%02d", sign, hour, minute)
183	}
184	
185	// validateCollectedAtText guards the one gap in time.Parse(RFC3339) that the
186	// instant-level check cannot see: the standard library folds an out-of-range
187	// numeric timezone offset instead of rejecting it — "+00:60" parses as
188	// +01:00 and "+23:60" as +24:00 — and it accepts "+24:00"/"-24:00" even
189	// though the RFC3339 write layout cannot express them. The string has
190	// already passed time.Parse, so its shape is RFC3339 with a "Z" suffix or a
191	// six-character ±HH:MM suffix; here the offset's own hour and minute fields
192	// are required to be 00..23 and 00..59 with no carry-over between them.
193	func validateCollectedAtText(s string) error {
194		// "Z" is the only sign-less offset form; it denotes the zero offset.
195		if strings.HasSuffix(s, "Z") {
196			return nil
197		}
198		if len(s) < 6 {
199			return fmt.Errorf("timezone offset must be Z or ±HH:MM in %q", s)
200		}
201		off := s[len(s)-6:]
202		if (off[0] != '+' && off[0] != '-') || off[3] != ':' {
203			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
204		}
205		hour, ok1 := twoDecimalDigits(off[1:3])
206		minute, ok2 := twoDecimalDigits(off[4:6])
207		if !ok1 || !ok2 {
208			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
209		}
210		if hour > 23 {
211			return fmt.Errorf("timezone offset %s has hour %02d, must be 00-23", off, hour)
212		}
213		if minute > 59 {
214			return fmt.Errorf("timezone offset %s has minute %02d, must be 00-59 (out-of-range minutes are not folded into the hour)", off, minute)
215		}
216		return nil
217	}
218	
219	// twoDecimalDigits parses exactly two ASCII decimal digits.
220	func twoDecimalDigits(s string) (int, bool) {
221		if len(s) != 2 || s[0] < '0' || s[0] > '9' || s[1] < '0' || s[1] > '9' {
222			return 0, false
223		}
224		return int(s[0]-'0')*10 + int(s[1]-'0'), true
225	}
226	
227	// checkHeartbeatValues runs every context-free field-value rule in the single
228	// rejection order shared by the direct-submit and stored-data boundaries:
229	// node, seq, version, height, missed, then collected_at. It deliberately does
230	// NOT compare against a receive time: reading saved history has no receive
231	// time, and that submit-only rule lives in checkCollectedAtTiming.
232	func checkHeartbeatValues(h Heartbeat) *fieldValueError {
233		if e := checkNodeIDValue(h.NodeID); e != nil {
234			return e
235		}
236		if e := checkPositiveInt("seq", h.Seq); e != nil {
237			return e
238		}
239		if e := checkVersionValue(h.Version); e != nil {
240			return e
241		}
242		if e := checkNonNegativeInt("height", h.Height); e != nil {
243			return e
244		}
245		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
246			return e
247		}
248		return checkCollectedAtValue(h.CollectedAt)
249	}
250	
251	// checkCollectedAtTiming holds the single receive-time rule, which belongs to
252	// submission only: a collection time later than the receive time is refused;
253	// the same instant expressed in another timezone is equal and allowed. The
254	// stored-data read path never calls this, so reading history introduces no
255	// current time and no extra time limit.
256	func checkCollectedAtTiming(collected, receiveTime time.Time) error {
257		if collected.After(receiveTime) {
258			return fmt.Errorf("collected_at %s is later than receive time %s",
259				collected.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
260		}
261		return nil
262	}
263	
264	// directError renders a field rule failure in ValidateHeartbeat's wording,
265	// used when a caller submits an already constructed Heartbeat.
266	func (e *fieldValueError) directError() error {
267		switch {
268		case e.field == "node" && e.issue == issueEmpty:
269			return fmt.Errorf("node id is empty")
270		case e.field == "node" && e.issue == issueInvalidUnicode:
271			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
272		case e.field == "seq":
273			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
274		case e.field == "version" && e.issue == issueInvalidUnicode:
275			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
276		case e.field == "version":
277			return fmt.Errorf("version is empty")
278		case e.field == "height":
279			return fmt.Errorf("height must be >= 0, got %d", e.value)
280		case e.field == "missed":
281			return fmt.Errorf("missed must be >= 0, got %d", e.value)
282		case e.field == "collected_at":
283			switch e.issue {
284			case issueMissingInstant:
285				return fmt.Errorf("collected_at is missing or invalid")
286			case issueYearOutOfRange:
287				return fmt.Errorf("collected_at year %d cannot be saved: year must be 0000-9999", e.value)
288			case issueOffsetOutOfRange:
289				return fmt.Errorf("collected_at timezone offset %s cannot be saved exactly: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
290			}
291			return fmt.Errorf("collected_at is missing or invalid")
292		default:
293			return fmt.Errorf("field %q has an invalid value", e.field)
294		}
295	}
296	
297	// decodeError renders a field rule failure in the wording used while decoding
298	// a strict JSON object (submit input and stored records alike).
299	func (e *fieldValueError) decodeError() error {
300		switch {
301		case e.field == "node" && e.issue == issueInvalidUnicode:
302			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
303		case e.field == "node":
304			return fmt.Errorf("node must not be empty")
305		case e.field == "seq":
306			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
307		case e.field == "version" && e.issue == issueInvalidUnicode:
308			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
309		case e.field == "version":
310			return fmt.Errorf("version must not be empty")
311		case e.field == "height":
312			return fmt.Errorf("height must be >= 0, got %d", e.value)
313		case e.field == "missed":
314			return fmt.Errorf("missed must be >= 0, got %d", e.value)
315		case e.field == "collected_at":
316			switch e.issue {
317			case issueMissingInstant:
318				return fmt.Errorf("collected_at is missing or invalid")
319			case issueYearOutOfRange:
320				return fmt.Errorf("collected_at year %d is out of range: year must be 0000-9999", e.value)
321			case issueOffsetOutOfRange:
322				return fmt.Errorf("collected_at timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
323			}
324			return fmt.Errorf("collected_at is missing or invalid")
325		default:
326			return fmt.Errorf("invalid value for field %q", e.field)
327		}
328	}
329	
330	// storedError renders a field rule failure for a record read from a saved
331	// file, prefixing the 1-based record position as stored-data errors do.
332	func (e *fieldValueError) storedError(position int) error {
333		switch {
334		case (e.field == "node" || e.field == "version") && e.issue == issueInvalidUnicode:
335			return fmt.Errorf("record %d: field %q is not valid Unicode text", position, e.field)
336		case e.field == "node" || e.field == "version":
337			return fmt.Errorf("record %d: field %q must not be empty", position, e.field)
338		case e.field == "seq":
339			return fmt.Errorf("record %d: field %q must be a positive integer, got %d", position, e.field, e.value)
340		case e.field == "height" || e.field == "missed":
341			return fmt.Errorf("record %d: field %q must be >= 0, got %d", position, e.field, e.value)
342		case e.field == "collected_at":
343			switch e.issue {
344			case issueYearOutOfRange:
345				return fmt.Errorf("record %d: field %q year %d is out of range: year must be 0000-9999", position, e.field, e.value)
346			case issueOffsetOutOfRange:
347				return fmt.Errorf("record %d: field %q timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", position, e.field, formatOffsetSeconds(int(e.value)))
348			}
349			return fmt.Errorf("record %d: field %q is missing or invalid", position, e.field)
350		default:
351			return fmt.Errorf("record %d: field %q has an invalid value", position, e.field)
352		}
353	}
354	
355	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
356	// the moment the platform received the batch; a collection time later than
357	// receive time is rejected. The field-value rules are shared with JSON
358	// parsing and the stored-file read path via checkHeartbeatValues; only the
359	// receive-time comparison is submit-specific.
360	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
361		if e := checkHeartbeatValues(h); e != nil {
362			return e.directError()
363		}
364		return checkCollectedAtTiming(h.CollectedAt, receiveTime)
365	}
366	
367	// Equal reports whether two records are the same telemetry. Collection times
368	// are compared as instants, so the same moment expressed in different
369	// timezones compares equal.
370	func (h Heartbeat) Equal(o Heartbeat) bool {
371		return h.NodeID == o.NodeID &&
372			h.Seq == o.Seq &&
373			h.Version == o.Version &&
374			h.Height == o.Height &&
375			h.Missed == o.Missed &&
376			h.CollectedAt.Equal(o.CollectedAt)
377	}
378	
379	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
380	// be explicitly provided; missing or unknown fields are rejected with a
381	// specific reason.
382	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
383		var raw []json.RawMessage
384		if err := json.Unmarshal(data, &raw); err != nil {
385			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
386		}
387		if len(raw) == 0 {
388			return nil, fmt.Errorf("no heartbeat records provided")
389		}
390		records := make([]Heartbeat, 0, len(raw))
391		for i, r := range raw {
392			h, err := parseOneHeartbeat(r, receiveTime)
393			if err != nil {
394				return nil, fmt.Errorf("record %d: %w", i+1, err)
395			}
396			records = append(records, h)
397		}
398		return records, nil
399	}
400	
401	// rejectNull reports an error when a required field's JSON value is null.
402	// A null value means the node did not report the field, which must not be
403	// silently saved as the zero value.
404	func rejectNull(raw json.RawMessage, field string) error {
405		if bytes.Equal(raw, []byte("null")) {
406			return fmt.Errorf("%s must not be null", field)
407		}
408		return nil
409	}
410	
411	// objectFields collects the fields of one JSON object while enforcing the
412	// single field-uniqueness rule shared by every strict decoder in this
413	// package: within one object, a field name may appear only once. Names are
414	// compared as the JSON strings they decode to, so a plain spelling and a
415	// Unicode-escaped spelling of the same name collide, whether the repeated
416	// value is identical or different. The rule is scoped to the current object:
417	// the same field name appearing in another heartbeat object is unrelated.
418	// Both the submit-input decoder (decodeStrictHeartbeatObject) and the
419	// stored-file envelope decoder (decodeStrictNodeFile) apply the rule through
420	// this type; each boundary keeps its own error wording and its own check
421	// ordering for the rejection.
422	//
423	// A nil map value means the name has been seen but its value not decoded
424	// yet; once decoded, the value is stored under the name.
425	type objectFields map[string]json.RawMessage
426	
427	// check records one occurrence of a field name and reports whether the name
428	// already appeared in this object (duplicate == true).
429	func (o objectFields) check(name string) (duplicate bool) {
430		if _, exists := o[name]; exists {
431			return true
432		}
433		o[name] = nil
434		return false
435	}
436	
437	// has reports whether the field name appeared in this object.
438	func (o objectFields) has(name string) bool {
439		_, exists := o[name]
440		return exists
441	}
442	
443	// decodeStrictHeartbeatObject converts one JSON object's raw bytes into a
444	// Heartbeat while enforcing the field rules at every trust boundary: all
445	// fields must be present and non-null, unknown fields are rejected, and a
446	// field may never appear twice in the same object — even with the same
447	// value, and even when one spelling uses a JSON Unicode escape denoting the
448	// same key (the shared objectFields rule). A plain struct/map unmarshal
449	// would instead keep the last
450	// occurrence and let an absent field masquerade as the zero value. Both the
451	// submit input path and the stored-file read path must use it.
452	func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
453		// Walk the object with a streaming decoder so duplicate field names are
454		// detected. Field names are compared as the JSON string they represent:
455		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
456		// would silently keep only the last occurrence.
457		dec := json.NewDecoder(bytes.NewReader(raw))
458		tok, err := dec.Token()
459		if err != nil {
460			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
461		}
462		if d, ok := tok.(json.Delim); !ok || d != '{' {
463			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
464		}
465	
466		fields := objectFields{}
467		for dec.More() {
468			keyTok, err := dec.Token()
469			if err != nil {
470				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
471			}
472			key, ok := keyTok.(string)
473			if !ok {
474				return Heartbeat{}, fmt.Errorf("field name must be a string")
475			}
476			if fields.check(key) {
477				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
478			}
479			var val json.RawMessage
480			if err := dec.Decode(&val); err != nil {
481				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
482			}
483			fields[key] = val
484		}
485		// Consume the closing brace.
486		if _, err := dec.Token(); err != nil {
487			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
488		}
489	
490		for _, f := range heartbeatFields {
491			if !fields.has(f) {
492				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
493			}
494		}
495		for k := range fields {
496			if !containsString(heartbeatFields, k) {
497				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
498			}
499		}
500	
501		var h Heartbeat
502	
503		if err := rejectNull(fields["node"], "node"); err != nil {
504			return Heartbeat{}, err
505		}
506		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
507			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
508		}
509		if err := validateRawText(fields["node"], "node"); err != nil {
510			return Heartbeat{}, err
511		}
512		if e := checkNodeIDValue(h.NodeID); e != nil {
513			return Heartbeat{}, e.decodeError()
514		}
515	
516		if err := rejectNull(fields["seq"], "seq"); err != nil {
517			return Heartbeat{}, err
518		}
519		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
520			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
521		}
522		if e := checkPositiveInt("seq", h.Seq); e != nil {
523			return Heartbeat{}, e.decodeError()
524		}
525	
526		if err := rejectNull(fields["collected_at"], "collected_at"); err != nil {
527			return Heartbeat{}, err
528		}
529		var collectedStr string
530		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
531			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
532		}
533		t, err := time.Parse(time.RFC3339, collectedStr)
534		if err != nil {
535			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
536		}
537		// time.Parse folds out-of-range numeric offsets (+00:60 -> +01:00) and
538		// accepts +24:00; verify the written offset before trusting the fold.
539		if err := validateCollectedAtText(collectedStr); err != nil {
540			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
541		}
542		h.CollectedAt = t
543	
544		if err := rejectNull(fields["version"], "version"); err != nil {
545			return Heartbeat{}, err
546		}
547		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
548			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
549		}
550		if err := validateRawText(fields["version"], "version"); err != nil {
551			return Heartbeat{}, err
552		}
553		if e := checkVersionValue(h.Version); e != nil {
554			return Heartbeat{}, e.decodeError()
555		}
556	
557		if err := rejectNull(fields["height"], "height"); err != nil {
558			return Heartbeat{}, err
559		}
560		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
561			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
562		}
563		if e := checkNonNegativeInt("height", h.Height); e != nil {
564			return Heartbeat{}, e.decodeError()
565		}
566	
567		if err := rejectNull(fields["missed"], "missed"); err != nil {
568			return Heartbeat{}, err
569		}
570		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
571			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
572		}
573		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
574			return Heartbeat{}, e.decodeError()
575		}
576	
577		return h, nil
578	}
579	
580	// validateRawText checks the raw JSON string token of a text field (node or
581	// version) before its decoded value is trusted. encoding/json silently rewrites
582	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
583	// would merge distinct texts into one replacement-char value: distinct node
584	// ids would collapse and break the ownership check against stored files, and
585	// distinct versions would collapse into text the node never reported,
586	// corrupting dedup and the version-skew judgement. The raw token must decode
587	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
588	// escape must be a valid scalar value or a properly paired high/low
589	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
590	// user typed and is accepted; only undecodable input is rejected. A \\
591	// escape is consumed as a unit, so text that genuinely contains a backslash
592	// followed by "u" and hex digits is never re-interpreted as an escape.
593	func validateRawText(raw json.RawMessage, field string) error {
594		raw = bytes.TrimSpace(raw)
595		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
596			return fmt.Errorf("%s must be a string", field)
597		}
598		s := raw[1 : len(raw)-1]
599		for i := 0; i < len(s); {
600			c := s[i]
601			if c == '\\' {
602				if i+1 >= len(s) {
603					return fmt.Errorf("%s contains a truncated escape", field)
604				}
605				if s[i+1] != 'u' {
606					i += 2
607					continue
608				}
609				if i+6 > len(s) {
610					return fmt.Errorf("%s contains a truncated \\u escape", field)
611				}
612				r, err := parseHex4(s[i+2 : i+6])
613				if err != nil {
614					return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
615				}
616				switch {
617				case r >= 0xD800 && r <= 0xDBFF:
618					// A high surrogate is only valid when immediately followed
619					// by a low-surrogate \u escape.
620					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
621						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
622					}
623					lo, err := parseHex4(s[i+8 : i+12])
624					if err != nil {
625						return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
626					}
627					if lo < 0xDC00 || lo > 0xDFFF {
628						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
629					}
630					i += 12
631				case r >= 0xDC00 && r <= 0xDFFF:
632					return fmt.Errorf("%s contains an unpaired low surrogate \\u%04X", field, r)
633				default:
634					i += 6
635				}
636				continue
637			}
638			if c < utf8.RuneSelf {
639				i++
640				continue
641			}
642			// A valid multi-byte rune decodes with size >= 2; size 1 means the
643			// bytes are not valid UTF-8 (including surrogate encodings).
644			_, size := utf8.DecodeRune(s[i:])
645			if size == 1 {
646				return fmt.Errorf("%s contains invalid UTF-8 at byte offset %d", field, i)
647			}
648			i += size
649		}
650		return nil
651	}
652	
653	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
654	func parseHex4(b []byte) (rune, error) {
655		v := 0
656		for _, c := range b {
657			var d int
658			switch {
659			case '0' <= c && c <= '9':
660				d = int(c - '0')
661			case 'a' <= c && c <= 'f':
662				d = int(c-'a') + 10
663			case 'A' <= c && c <= 'F':
664				d = int(c-'A') + 10
665			default:
666				return 0, fmt.Errorf("invalid hex digit %q", c)
667			}
668			v = v*16 + d
669		}
670		return rune(v), nil
671	}
672	
673	// parseOneHeartbeat decodes one submit-input record and applies the
674	// submit-only rule that collection time cannot be later than receive time.
675	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
676		h, err := decodeStrictHeartbeatObject(raw)
677		if err != nil {
678			return Heartbeat{}, err
679		}
680		if err := checkCollectedAtTiming(h.CollectedAt, receiveTime); err != nil {
681			return Heartbeat{}, err
682		}
683		return h, nil
684	}
685	
686	func containsString(list []string, s string) bool {
687		for _, v := range list {
688			if v == s {
689				return true
690			}
691		}
692		return false
693	}
