178			}
179			os.Exit(2)
180		}
181		if fs.NArg() != 0 {
182			die("submit takes no positional arguments; heartbeats are read from stdin")
183		}
184	
185		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
186	
187		data, err := io.ReadAll(os.Stdin)
188		if err != nil {
189			die("cannot read stdin: %v", err)
190		}
191		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
192		if err != nil {
193			die("invalid input: %v", err)
194		}
195	
196		store, err := edgefleet.OpenStore(*dataDir)
197		if err != nil {
198			die("%v", err)
199		}
200		newCount, dupCount, err := store.Submit(records, receiveTime)
201		if err != nil {
202			die("%v", err)
