	case "demo":
		runDemo()
	case "version":
		fmt.Println("edgefleet 0.1.0")
	case "heartbeat":
		runHeartbeat(os.Args[2:])
	case "help", "-h", "--help":
		usage()
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
