61	// runCLI invokes the re-executed binary with the given arguments. stdin is
62	// fed to the command (used by `heartbeat submit`). It returns the captured
63	// stdout, stderr and exit code.
64	func runCLI(t *testing.T, dir, stdin string, args ...string) (string, string, int) {
65		t.Helper()
66		cmd := exec.Command(os.Args[0], args...)
67		cmd.Stdin = strings.NewReader(stdin)
