413	// envelope wraps a raw records array in a well-formed store file.
414	func envelope(checksum, recordsJSON string) string {
415		return `{"format":"edgefleet-heartbeats-v1","checksum":"` + checksum + `","records":` + recordsJSON + `}`
416	}
