418	// TestCLIStoredCorruptionRefusedByQueries exercises the user-visible contract:
419	// a saved record with a missing, null or duplicated telemetry field corrupts
420	// the node's data even when the checksum matches the interpreted values; every
421	// query for that node fails on stderr with a non-zero exit and prints nothing
422	// on stdout, while other nodes keep working.
423	func TestCLIStoredCorruptionRefusedByQueries(t *testing.T) {
424		f := newFixture(t)
425	
426		const badRecord = `{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}`
427		submitBatch(t, f.dir, "["+badRecord+"]")
428	
429		cases := []struct {
430			name        string
431			tamper      string // raw records array stored alongside a matching checksum
432			interpreted string // canonical records a lenient reader reconstructs
433			wantField   string
434		}{
435			{
436				name:        "missing missed stays matching with original checksum",
437				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100}]`,
438				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`,
439				wantField:   "missed",
440			},
441			{
442				name:        "null height with checksum over zero-filled value",
443				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":null,"missed":0}]`,
444				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":0,"missed":0}]`,
445				wantField:   "height",
446			},
447			{
448				name:        "duplicate missed same value, last-wins interpretation matches",
449				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0,"missed":0}]`,
450				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`,
451				wantField:   "missed",
452			},
453		}
454	
455		for _, tc := range cases {
456			t.Run(tc.name, func(t *testing.T) {
457				// The forged checksum hashes the canonical record a lenient
458				// reader would reconstruct (zero-filled / last value).
459				corruptNodeFile(t, f.dir, "bad", envelope(strictChecksum(tc.interpreted), tc.tamper))
460	
461				// history: non-zero exit, explicit reason on stderr naming the
462				// file/record/field, no normal output on stdout.
463				out, errOut, code := runCLI(t, f.dir, "",
464					"heartbeat", "history", "--data-dir", f.dir, "--node", "bad")
465				if code == 0 {
466					t.Errorf("history on corrupt node must exit non-zero; stdout=%q", out)
467				}
468				if out != "" {
469					t.Errorf("history must print no results on corruption, stdout=%q", out)
470				}
471				if !strings.Contains(errOut, "error:") || !strings.Contains(errOut, "record 1") ||
472					!strings.Contains(errOut, tc.wantField) {
473					t.Errorf("history stderr must explain the corrupt record/field, got %q", errOut)
474				}
475				if !strings.Contains(errOut, filepath.Base(nodeFileHexPath(f.dir, "bad"))) {
476					t.Errorf("history stderr should identify the corrupt file, got %q", errOut)
477				}
478	
479				// health: same contract.
480				out, errOut, code = health(t, f,
481					"--node", "bad", "--expected-version", "1.26.0", "--tolerated-misses", "0")
482				if code == 0 {
483					t.Errorf("health on corrupt node must exit non-zero; stdout=%q", out)
484				}
485				if out != "" {
486					t.Errorf("health must print no results on corruption, stdout=%q", out)
487				}
488				if !strings.Contains(errOut, "record 1") || !strings.Contains(errOut, tc.wantField) {
489					t.Errorf("health stderr must explain the corrupt record/field, got %q", errOut)
490				}
491	
492				// health with a missed-duty baseline must fail identically rather
493				// than skipping the bad record.
494				out, errOut, code = health(t, f,
495					"--node", "bad", "--expected-version", "1.26.0",
496					"--tolerated-misses", "0", "--missed-since-seq", "1")
497				if code == 0 {
498					t.Errorf("baseline health on corrupt node must exit non-zero; stdout=%q", out)
499				}
500				if out != "" {
501					t.Errorf("baseline health must print no results on corruption, stdout=%q", out)
502				}
503				if !strings.Contains(errOut, tc.wantField) {
504					t.Errorf("baseline health stderr must name the field, got %q", errOut)
505				}
506			})
507		}
508	}
