510	// TestCLISubmitRejectsBatchTouchingCorruptNode ensures a batch is refused
511	// before any new record is saved: the corrupt file stays byte-for-byte
512	// intact, other files in the batch are not written, and no new node file is
513	// created. Submitting only to healthy nodes continues to work.
514	func TestCLISubmitRejectsBatchTouchingCorruptNode(t *testing.T) {
515		f := newFixture(t)
516	
517		const canonical = `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`
518		submitBatch(t, f.dir, "["+strings.Trim(canonical, "[]")+"]")
519		// Delete "missed" from the genuine record (its value was 0); keep the
520		// original checksum, which still matches the zero-filled interpretation.
521		corruptNodeFile(t, f.dir, "bad", envelope(strictChecksum(canonical),
522			`[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100}]`))
523	
524		badBefore := readNodeFile(t, f.dir, "bad")
525		monoBefore := readNodeFile(t, f.dir, "mono")
526	
527		batch := `[
528		  {"node":"bad","seq":2,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":102,"missed":0},
529		  {"node":"mono","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":104,"missed":15},
530		  {"node":"brandnew","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}
531		]`
532		out, errOut, code := runCLI(t, f.dir, batch,
533			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
534		if code == 0 {
535			t.Errorf("submit touching a corrupt node must fail non-zero; stdout=%q stderr=%q", out, errOut)
536		}
537		if strings.Contains(out, "submitted") {
538			t.Errorf("rejected batch must not report success, stdout=%q", out)
539		}
540		if !strings.Contains(errOut, "corruption") || !strings.Contains(errOut, "missed") {
541			t.Errorf("submit stderr must explain the corruption, got %q", errOut)
542		}
543	
544		if got := readNodeFile(t, f.dir, "bad"); got != badBefore {
545			t.Errorf("corrupt node file was modified during rejected submit")
546		}
547		if got := readNodeFile(t, f.dir, "mono"); got != monoBefore {
548			t.Errorf("healthy node file was rewritten during rejected submit")
549		}
550		if _, err := os.Stat(nodeFileHexPath(f.dir, "brandnew")); !os.IsNotExist(err) {
551			t.Errorf("brand-new node file must not be created, stat err=%v", err)
552		}
553	
554		// Healthy nodes are unaffected and remain fully usable.
555		out, _, code = health(t, f,
556			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
557		if code != 0 || !strings.Contains(out, "node=mono") {
558			t.Errorf("healthy node must still query normally: code=%d out=%q", code, out)
559		}
560		submitBatch(t, f.dir, `[{"node":"gappy","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":304,"missed":4}]`)
561	}
