package edgefleet

import (
	"errors"
	"fmt"
	"os"
	"strings"
	"testing"
	"time"
)

// scratch verification of write-failure injection semantics (throwaway).
func TestScratchPartialPersist(t *testing.T) {
	dir := t.TempDir()
	store, err := OpenStore(dir)
	if err != nil {
		t.Fatal(err)
	}
	receive := testBase

	seed := []Heartbeat{
		hb("alpha", 1, receive.Add(-2*time.Minute), "1.0", 100, 0),
		hb("beta", 1, receive.Add(-2*time.Minute), "1.0", 200, 0),
	}
	if _, _, err := store.Submit(seed, receive); err != nil {
		t.Fatal(err)
	}

	batch := []Heartbeat{
		hb("alpha", 2, receive.Add(-time.Minute), "1.0", 101, 0),
		hb("alpha", 2, receive.Add(-time.Minute), "1.0", 101, 0),
		hb("beta", 2, receive.Add(-time.Minute), "1.0", 201, 1),
		hb("beta", 1, receive.Add(-2*time.Minute), "1.0", 200, 0),
	}

	// Run the failure at each possible injection point to observe map order.
	for failAt := 1; failAt <= 2; failAt++ {
		for iter := 0; iter < 5; iter++ {
			calls := 0
			realWriter := writeNodeFile
			writeNodeFile = func(path string, records []Heartbeat) error {
				calls++
				if calls == failAt {
					return errors.New("injected write failure")
				}
				return realWriter(path, records)
			}
			n, d, err := store.Submit(batch, receive)
			writeNodeFile = realWriter
			if err == nil {
				t.Fatalf("failAt=%d iter=%d: expected error", failAt, iter)
			}
			a, _ := store.History("alpha")
			b, _ := store.History("beta")
			t.Logf("failAt=%d iter=%d calls=%d n=%d d=%d errWrap=%v alpha=%d beta=%d",
				failAt, iter, calls, n, d, strings.Contains(err.Error(), "failed to persist heartbeat batch"), len(a), len(b))
			// reset: rebuild from seed into a fresh store dir
			dir2 := t.TempDir()
			store, _ = OpenStore(dir2)
			if _, _, err := store.Submit(seed, receive); err != nil {
				t.Fatal(err)
			}
		}
	}

	// Verify file path identity check works.
	locA := store.nodeLocationFor("alpha")
	locB := store.nodeLocationFor("beta")
	t.Logf("paths differ: %v  %s vs %s", locA.path != locB.path, locA.path, locB.path)
	_ = os.TempDir
	fmt.Println()
}

